function extractCodeFromSubject(subject) {
  const match = String(subject == null ? '' : subject).match(/FAR-\d{4}/i);
  return match ? match[0].toUpperCase() : '';
}
function extractReplyAddress(from) {
  const raw = String(from == null ? '' : from).trim();
  if (!raw) return '';
  const angled = raw.match(/<([^<>]+)>/);
  return angled ? angled[1].trim() : raw;
}
function sanitizeFilename(name) {
  const raw = String(name == null ? '' : name).replace(/\\/g, '/');
  const parts = raw.split('/').filter(function (part) { return part !== '' && part !== '.' && part !== '..'; });
  let base = parts.length ? parts[parts.length - 1] : '';
  base = base.replace(/\s+/g, '_').replace(/[^A-Za-z0-9._-]/g, '').replace(/\.{2,}/g, '.');
  return base || 'receta-adjunta';
}
let items = [];
if (typeof $ !== 'undefined') {
  const messages = $.input.all();
  for (const entry of messages) {
    const json = entry.json || {};
    const binary = entry.binary || {};
    const keys = Object.keys(binary);
    const firstKey = keys.length ? keys[0] : '';
    const attachment = firstKey ? binary[firstKey] : null;
    const safeFilename = attachment ? sanitizeFilename(attachment.fileName || attachment.file || '') : '';
    const item = { json: { source: 'email', reply_to: extractReplyAddress(json.from), subject: String(json.subject == null ? '' : json.subject), codigo_far: extractCodeFromSubject(json.subject), hasAttachment: Boolean(attachment), safeFilename: safeFilename } };
    if (attachment) { item.binary = { attachment: attachment }; }
    items.push(item);
  }
}
return items;

function classifyAction(input) {
  const codigo = input.codigo_far;
  const order = input.order;
  if (!codigo) return 'ASK_CODE';
  if (!order || String(order.estado).trim().toUpperCase() !== 'PENDIENTE_RECETA') return 'NOT_PENDING';
  if (!input.hasAttachment) return 'ASK_ATTACHMENT';
  return 'UPLOAD';
}
function buildRecipeMessage(action, codigoFar) {
  const code = codigoFar ? '#' + codigoFar : '';
  if (action === 'ASK_CODE') return 'No encontré un código de pedido (#FAR-XXXX) en el asunto de tu correo. Reenvía el mensaje con el código en el asunto.';
  if (action === 'ASK_ATTACHMENT') return 'Tu pedido ' + code + ' está esperando la receta. Responde a este correo adjuntando la foto o el PDF de la receta.';
  if (action === 'NOT_PENDING') return 'Tu pedido ' + code + ' no está esperando receta. Consulta su estado en la farmacia.';
  if (action === 'SUCCESS') return 'Recibimos la receta de tu pedido ' + code + '. Ya pasa a preparación.';
  return '';
}
function buildDriveName(codigo, timestampMs, safeFilename) {
  return `${codigo}/${timestampMs}-${safeFilename}`;
}
let items = [];
if (typeof $ !== 'undefined') {
  const parsedItem = $('parse_recipe_email').first();
  const parsed = parsedItem.json;
  const orders = $('read_ordenes').all().map(function (entry) { return entry.json; });
  const wanted = parsed.codigo_far ? String(parsed.codigo_far).toUpperCase() : '';
  const order = wanted ? orders.find(function (row) { return String(row.codigo_far == null ? '' : row.codigo_far).trim().toUpperCase() === wanted; }) : undefined;
  const action = classifyAction({ codigo_far: parsed.codigo_far, hasAttachment: parsed.hasAttachment, order: order });
  const message = action === 'UPLOAD' ? '' : buildRecipeMessage(action, parsed.codigo_far);
  const driveName = buildDriveName(parsed.codigo_far || 'SIN-CODIGO', Date.now(), parsed.safeFilename || 'receta-adjunta');
  const out = { json: { source: parsed.source, reply_to: parsed.reply_to, subject: 'Re: ' + parsed.subject, codigo_far: parsed.codigo_far, hasAttachment: parsed.hasAttachment, safeFilename: parsed.safeFilename, driveName: driveName, medicamento_id: order ? order.medicamento_id : '', action: action, message: message } };
  if (parsedItem.binary) { out.binary = parsedItem.binary; }
  items.push(out);
}
return items;

